      "target": "sceneRecordDeath",
      "kind": "method",
      "before": "recordDeath(): void {\n    this.loseBagRelicsOnDeath(this.localSeat);\n    if (this.inCave) return;\n    const loot = captureLoot(this.meta);\n    if (loot.items.length === 0) return;\n    const rec: DeathRecord = {\n      schema: DEATH_SCHEMA,\n      mapX: this.zone.map.x, mapY: this.zone.map.y,\n      pos: { x: this.player.pos.x, y: this.player.pos.y },\n      zoneId: this.zone.id,\n      loot,\n      classId: this.meta.classDef.id, charLevel: this.player.level, zoneName: this.zone.name,\n      owner: this.localSeat.id,\n      timestamp: Date.now(),\n    };\n    const own = this.modeStageDef().corpseRing === 'own';\n    const ring = own ? this.charDeaths : this.account.deaths;\n    ring.push(rec);\n    while (ring.length > MAX_DEATH_RECORDS) ring.shift();\n    if (own) this.charDirty = true; // rides the character save, not the account\n  }",
